import type {
	ConsoleHostOptions,
	HostFile
} from '../../../utils/development-tooling/consoleHostFiles';
import { consoleServerDirectory } from '../../../utils/development-tooling/consoleHostFiles';
import { emptyBuildStamp } from '../../../utils/development-tooling/buildStamp';

const header =
	'// Generated by `harness console install`. Run the command again instead of editing this file.\n';

const access = "import { harness } from '$lib/server/harness/console';\n";

/** History compiled into the server: modules only server code can import, loaded when asked for. */
const bundled = `// History and media are modules of this server bundle, loaded only when asked for. Nothing
// under $lib/server can be imported by client code, so they have no public path.
const data = consoleBundle({
	json: import.meta.glob([
		'./data/index.json.ts',
		'./data/activity.json.ts',
		'./data/revisions/*.json.ts',
		'./data/sides/*.json.ts'
	]),
	media: import.meta.glob('./data/media/*.ts')
});
`;

/** History read from a private bucket binding of the request, after the policy admitted it. */
function stored(bucket: { binding: string; prefix: string }): string {
	return `// History and media stay in the private bucket bound as ${bucket.binding}. A binding has no
// public address: the handlers below are the only way to it, and they ask the policy first.
function data(event: ConsoleRequest) {
	const env = (event.platform as { env?: Record<string, unknown> } | undefined)?.env;
	const bucket = env?.['${bucket.binding}'] as ConsoleBucket | undefined;
	if (!bucket) throw new Error('The ${bucket.binding} binding is missing from this deployment.');
	return consoleStore(bucket, '${bucket.prefix}');
}
`;
}

function serverModule(options: ConsoleHostOptions): string {
	const { bucket } = options;
	const kit = bucket
		? `import { consoleAccess, consoleDocument, consoleStore } from '@dafuga01/harness/console';
import type { ConsoleBucket, ConsoleRequest } from '@dafuga01/harness/console';`
		: "import { consoleAccess, consoleBundle, consoleDocument } from '@dafuga01/harness/console';";
	return `${header}${kit}
import { consoleAssets, consoleExporter } from '@dafuga01/harness/console-ui';
import { ${options.policyExport} as policy } from '${options.policyModule}';

${bucket ? stored(bucket) : bundled}
// What this deployment says it is: the revision its build was given, and the identity that
// \`harness verify stamp\` writes into the emitted files in place of this empty slot.
const host = {
	revision: import.meta.env.VITE_HARNESS_HOST_REVISION as string | undefined,
	build: '${emptyBuildStamp()}'
};

/** Every console response goes through the host's own policy first. */
export const harness = consoleAccess({ policy, data, exporter: consoleExporter, host });

const html = consoleDocument(consoleAssets, { base: '${options.base}', exportable: true });

/** The console document: the viewer only, sent once the policy has admitted the request. */
export function consolePage(): Response {
	return new Response(html, {
		headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'private, no-store' }
	});
}
`;
}

/** The console document for the root and for every page path; both answer through `entry`. */
function documentRoute(base: string): string {
	return `${header}import type { RequestEvent } from '@sveltejs/kit';
import { consolePage, harness } from '$lib/server/harness/console';

export async function GET(event: RequestEvent): Promise<Response> {
	return (await harness.entry(event, '${base}')) ?? consolePage();
}
`;
}

const routes: Array<[string, string]> = [
	[
		'data/[...path]/+server.ts',
		`${header}import type { RequestEvent } from '@sveltejs/kit';
${access}
export function GET(event: RequestEvent): Promise<Response> {
	return harness.json(event, event.params.path ?? '');
}
`
	],
	[
		'export/[commit]/+server.ts',
		`${header}import type { RequestEvent } from '@sveltejs/kit';
${access}
export function GET(event: RequestEvent): Promise<Response> {
	const record = event.url.searchParams.get('record');
	return harness.report(event, event.params.commit ?? '', record);
}
`
	],
	[
		'media/[file]/+server.ts',
		`${header}import type { RequestEvent } from '@sveltejs/kit';
${access}
export function GET(event: RequestEvent): Promise<Response> {
	return harness.media(event, event.params.file ?? '');
}
`
	]
];

/**
 * The files a SvelteKit host needs to serve the console: one server-only module that binds
 * the host's policy to the data, the console document for the root and for every page path,
 * and the data, export and media endpoints. All of them answer through it and nothing else.
 */
export function consoleHostFiles(options: ConsoleHostOptions): HostFile[] {
	return [
		{ path: `${consoleServerDirectory}/console.ts`, contents: serverModule(options) },
		{ path: `src/routes${options.base}/+server.ts`, contents: documentRoute(options.base) },
		{
			path: `src/routes${options.base}/[...view]/+server.ts`,
			contents: documentRoute(options.base)
		},
		...routes.map(([path, contents]) => ({
			path: `src/routes${options.base}/${path}`,
			contents
		}))
	];
}
